chapter.sect1:
  &reftitle.examples;




    आधारभूत सीमित मानहरू (Basic limited values)


<?php

enum SortOrder
{
    case Asc;
    case Desc;
}

function query($fields, $filter, SortOrder $order = SortOrder::Asc)
{
     /* ... */
}




     अब query() function ले $order निश्चित रूपमा SortOrder::Asc वा SortOrder::Desc नै हो भन्ने कुरामा ढुक्क भएर अगाडि बढ्न सक्छ। अन्य कुनै पनि मानले TypeError निम्त्याउने भएकोले, थप error जाँच वा परीक्षण आवश्यक पर्दैन।








    विशिष्ट मानहरूको उन्नत प्रयोग (Advanced exclusive values)



<?php

enum UserStatus: string
{
    case Pending = 'P';
    case Active = 'A';
    case Suspended = 'S';
    case CanceledByUser = 'C';

    public function label(): string
    {
        return match ($this) {
            self::Pending => 'Pending',
            self::Active => 'Active',
            self::Suspended => 'Suspended',
            self::CanceledByUser => 'Canceled by user',
        };
    }
}

$status = UserStatus::Suspended;
var_dump($status->label());





     यस उदाहरणमा, प्रयोगकर्ताको status केवल UserStatus::Pending,
     UserStatus::Active, UserStatus::Suspended, वा
     UserStatus::CanceledByUser मध्ये कुनै एक मात्र हुन सक्छ। कुनै function ले parameter को type UserStatus तोकेर केवल ती चार मानहरू मात्र स्वीकार गर्न सक्छ, अन्य कुनै पनि होइन।




     चारै वटा मानहरूसँग label() method छ, जसले मानिसले पढ्न सकिने (human-readable) string फर्काउँछ।
     त्यो string "machine name" scalar समकक्ष string भन्दा स्वतन्त्र हुन्छ, जसलाई उदाहरणका लागि database field वा HTML select box मा प्रयोग गर्न सकिन्छ।




<?php

enum UserStatus: string
{
    case Pending = 'P';
    case Active = 'A';
    case Suspended = 'S';
    case CanceledByUser = 'C';

    public function label(): string
    {
        return match($this) {
            self::Pending => 'Pending',
            self::Active => 'Active',
            self::Suspended => 'Suspended',
            self::CanceledByUser => 'Canceled by user',
        };
    }
}

foreach (UserStatus::cases() as $case) {
    printf(
        "<option value=\"%s\">%s</option>\n",
        htmlentities($case->value),
        htmlentities($case->label())
    );
}
